def split_commas(s):
    """Split on commas outside quoted display names and angle brackets."""
    parts = []
    cur = []
    i = 0
    n = len(s)
    in_q = False
    in_b = False
    while i < n:
        c = s[i]
        if in_q:
            if c == "\\":
                cur.append(c)
                i += 1
                if i < n:
                    cur.append(s[i])
                    i += 1
                continue
            if c == '"':
                in_q = False
            cur.append(c)
            i += 1
        elif in_b:
            if c == ">":
                in_b = False
            cur.append(c)
            i += 1
        else:
            if c == '"':
                in_q = True
                cur.append(c)
                i += 1
            elif c == "<":
                in_b = True
                cur.append(c)
                i += 1
            elif c == ",":
                parts.append("".join(cur))
                cur = []
                i += 1
            else:
                cur.append(c)
                i += 1
    parts.append("".join(cur))
    return parts


